import { test, expect } from '../../fixtures/index.js';
import { meta } from 'reporting-labs';
import { AccountRecordPage } from '../../pages/AccountRecordPage.js';
import { NewContactDialog } from '../../pages/NewContactDialog.js';
import {
  expectFieldError,
  expectRecordTitle,
  recordIdFromView,
  showRelatedList,
  waitForSpinners,
} from '../../support/lightning.js';
import { soqlCount } from '../../support/api.js';

test.describe('SF-219 Last Name maximum length boundary values (79, 80, 81 characters)', () => {
  test.describe.configure({ mode: 'parallel' });

  test(
    'TC-SF-219-004 Last Name maximum length boundary values (79, 80, 81 characters)',
    { tag: ['@negative', '@P2', '@SF-219', '@persona:system-admin', '@mandatory'] },
    async ({ page, data, sf }) => {
      meta({
        priority: 'P2',
        severity: 'minor',
        feature: 'Account',
        story: 'SF-219',
        owner: 'qa-agent',
        testCase: 'TC-SF-219-004',
      });
      const accountRecordPage = new AccountRecordPage(page);
      const newContactDialog = new NewContactDialog(page);
      const len79 = data.ofLength(79);
      const len80 = data.ofLength(80);
      const len81 = data.ofLength(81);
      const viewed: Record<string, string> = {};
      await data.create('account-contact', ['Account', 'Contact']);
      await test.step('1. Enter a Last Name with exactly 79 characters and click Save', async () => {
        // Expected (DECLARED_CONFIG; BRD-CON-012#BR-02, Field:Contact.LastName): The Contact is successfully created with the 79-character Last Name
        await accountRecordPage.open(data.id('Account'));
        await showRelatedList(accountRecordPage.contactsRelatedList, accountRecordPage.relatedTab);
        await accountRecordPage.contactsNewButton.click();
        await expect(newContactDialog.root).toBeVisible();
        await newContactDialog.lastName.fill(len79);
        await newContactDialog.saveButton.click();
        await waitForSpinners(page);
        await data.adopt('Contact', 'Contact', 'LastName', len79);
        viewed['Contact'] = await recordIdFromView(page, 'Contact');
        await expectRecordTitle(page, len79);
      });
      await test.step('2. Enter a Last Name with exactly 80 characters (maximum length) and click Save', async () => {
        // Expected (DECLARED_CONFIG; BRD-CON-012#BR-02, Field:Contact.LastName): The Contact is successfully created with the 80-character Last Name
        await accountRecordPage.open(data.id('Account'));
        await showRelatedList(accountRecordPage.contactsRelatedList, accountRecordPage.relatedTab);
        await accountRecordPage.contactsNewButton.click();
        await expect(newContactDialog.root).toBeVisible();
        await newContactDialog.lastName.fill(len80);
        await newContactDialog.saveButton.click();
        await waitForSpinners(page);
        await data.adopt('Contact', 'Contact', 'LastName', len80);
        viewed['Contact'] = await recordIdFromView(page, 'Contact');
        await expectRecordTitle(page, len80);
      });
      await test.step('3. Enter a Last Name with 81 characters (exceeding maximum length) and click Save', async () => {
        // Expected (DECLARED_CONFIG; BRD-CON-012#BR-02, Field:Contact.LastName): The Contact is not saved and an error is shown on the Last Name field
        await accountRecordPage.open(data.id('Account'));
        await showRelatedList(accountRecordPage.contactsRelatedList, accountRecordPage.relatedTab);
        await accountRecordPage.contactsNewButton.click();
        await expect(newContactDialog.root).toBeVisible();
        await newContactDialog.lastName.fill(len81);
        await newContactDialog.saveButton.click();
        await waitForSpinners(page);
        expect(await soqlCount(sf, 'Contact', 'LastName', len81)).toBe(0);
        await expectFieldError(newContactDialog.lastName);
      });
    },
  );
});
